public bool Enthaelt(int wert)
{
    Knoten? k = wurzel;
    while (k != null)
    {
        if (wert == k.Wert)
            return true;
        if (wert < k.Wert)
            k = k.Links;
        else
            k = k.Rechts;
    }
    return false;
}

int[] werte =
    { 50, 30, 70, 20, 40, 60, 80 };
var baum = new Suchbaum();
foreach (int x in werte)
    baum.Einfuegen(x);

baum.Ausgeben();
Console.WriteLine(baum.Enthaelt(60));
Console.WriteLine(baum.Enthaelt(65));
// Ausgabe:
// 20 30 40 50 60 70 80
// True
// False

class Suchbaum
{
    private Knoten? wurzel;

    public void Einfuegen(int wert) =>
        wurzel = Einf(wurzel, wert);

    private static Knoten Einf(
        Knoten? k, int wert)
    {
        // Platz gefunden: neues Blatt
        if (k == null)
            return new Knoten(wert);
        if (wert < k.Wert)
            k.Links = Einf(k.Links, wert);
        else if (wert > k.Wert)
            k.Rechts = Einf(k.Rechts, wert);
        return k; // gleich: ignorieren
    }

    // Enthaelt wie oben

    public void Ausgeben()
    {
        Inorder(wurzel);
        Console.WriteLine();
    }

    private static void Inorder(Knoten? k)
    {
        if (k == null) return;
        Inorder(k.Links);
        Console.Write(k.Wert + " ");
        Inorder(k.Rechts);
    }
}

// Suchbaum wie oben, ergänzt um eine
// Methode Hoehe() wie in der letzten
// Lektion
int[] gemischt = { 4, 2, 6, 1, 3, 5, 7 };
var a = new Suchbaum();
foreach (int x in gemischt)
    a.Einfuegen(x);

var b = new Suchbaum();
for (int x = 1; x <= 7; x++)
    b.Einfuegen(x);

Console.WriteLine(a.Hoehe());
Console.WriteLine(b.Hoehe());
// Ausgabe:
// 2
// 6

